builder.Services.AddCors(o => o.AddPolicy("Web",
    p => p.WithOrigins("https://app.com")  // only this origin
          .AllowAnyHeader().AllowAnyMethod()));

var app = builder.Build();
app.UseCors("Web");   // must come before MapControllers
app.MapControllers();

[Authorize(Roles = "Admin")]   // must be authenticated AND in Admin role
[HttpDelete("{id}")]
public IActionResult Delete(int id) { ... }

[AllowAnonymous]               // overrides Authorize for this one
[HttpGet("public")]
public IActionResult Public() { ... }

app.UseExceptionHandler(eh => eh.Run(async ctx =>
{
    ctx.Response.StatusCode = 500;          // one place for all errors
    await ctx.Response.WriteAsJsonAsync(
        new { error = "Something went wrong" }); // safe, no stack trace
}));

